node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Execute the exchange: update order status and set exchange fields
const diffPrice = Math.round((23.91 - 24.99) * 100) / 100; // -1.08

db.prepare(\`
  UPDATE orders 
  SET status = 'exchange requested',
      exchange_items = ?,
      exchange_new_items = ?,
      exchange_payment_method_id = ?,
      exchange_price_difference = ?
  WHERE order_id = '#W7231611'
\`).run(
  JSON.stringify(['3301828484']),
  JSON.stringify(['7389318502']),
  'credit_card_9958253',
  diffPrice
);

// Verify the update
const order = db.prepare(\"SELECT order_id, status, exchange_items, exchange_new_items, exchange_payment_method_id, exchange_price_difference FROM orders WHERE order_id = '#W7231611'\").get();
console.log('Updated order:', JSON.stringify(order, null, 2));
"
